PARAMS = ['Vmax','Km','Ki','f','n']
def predict(df, p):
    S = df['S'].values; I = df['I'].values
    # noncompetitive with partial floor f, inhibitor Hill slope n
    inh = 1/(1+(I/p['Ki'])**p['n'])
    return p['Vmax']*S/(p['Km']+S)*(p['f'] + (1-p['f'])*inh)

